_FA = str.maketrans("0123456789.", "۰۱۲۳۴۵۶۷۸۹٫")


def racks_to_templates(apps, schema_editor):
    """One line template per distinct live-rack geometry (length, arm, pieces); racks and their live slots are linked to it.
    Products (store_slot_products) and history are not touched. Soft-deleted racks and slots keep no template."""
    Layout = apps.get_model("store_map", "StoreLayout")
    Rack = apps.get_model("store_map", "Rack")
    RackSlot = apps.get_model("store_map", "RackSlot")
    Template = apps.get_model("store_map", "RackTemplate")
    Piece = apps.get_model("store_map", "TemplatePiece")
    for layout in Layout.objects.order_by("id"):
        groups, names = {}, set()
        for rack in Rack.objects.filter(layout=layout, deleted_at__isnull=True).order_by("id"):
            slots = list(RackSlot.objects.filter(rack=rack, deleted_at__isnull=True).order_by("side", "offset_cm", "id"))
            geometry = (rack.length_cm, rack.arm_cm, tuple((s.side, s.kind, s.offset_cm, s.length_cm) for s in slots))
            if geometry not in groups:
                sides = {s.side for s in slots}
                base = "رگال دیواری" if len(sides) == 1 else "رگال کامل و نیم" if any(s.kind == "half" for s in slots) else "رگال وسط دوطرفه"
                name = f"{base} {str((rack.length_cm or 0) / 100).removesuffix('.0').translate(_FA)} متری"
                n, unique = 2, name
                while unique in names:
                    unique, n = f"{name} {str(n).translate(_FA)}", n + 1
                names.add(unique)
                template = Template.objects.create(layout=layout, name=unique, kind="line", length_cm=rack.length_cm, arm_cm=rack.arm_cm)
                pieces = [Piece.objects.create(template=template, side=side, kind=kind, offset_cm=offset, length_cm=length)
                          for side, kind, offset, length in geometry[2]]
                groups[geometry] = (template, pieces)
            template, pieces = groups[geometry]
            Rack.objects.filter(id=rack.id).update(template=template)
            for slot, piece in zip(slots, pieces):
                RackSlot.objects.filter(id=slot.id).update(template_piece=piece)


